        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IGameplayRewardGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.RewardFormID, out var RewardFormIDInfo))
            {
                yield return RewardFormIDInfo;
            }
            if (FormLinkInformation.TryFactory(obj.CENT, out var CENTInfo))
            {
                yield return CENTInfo;
            }
            if (obj.Conditions is {} ConditionsItem)
            {
                foreach (var item in ConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.NAM9, out var NAM9Info))
            {
                yield return NAM9Info;
            }
            if (FormLinkInformation.TryFactory(obj.QRCO, out var QRCOInfo))
            {
                yield return QRCOInfo;
            }
            if (FormLinkInformation.TryFactory(obj.QRCX, out var QRCXInfo))
            {
                yield return QRCXInfo;
            }
            if (FormLinkInformation.TryFactory(obj.QRLR, out var QRLRInfo))
            {
                yield return QRLRInfo;
            }
            yield break;
        }
        
